CREATE DATABASE IF NOT EXISTS myportfolio CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE myportfolio;
CREATE TABLE IF NOT EXISTS admins(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profile(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL DEFAULT 'Your Name',site_name VARCHAR(120) DEFAULT NULL,age VARCHAR(30),university VARCHAR(200),programme VARCHAR(200),portrait_url VARCHAR(500) DEFAULT 'assets/images/idris-portrait.png',hero_label VARCHAR(160) DEFAULT 'COMPUTER SCIENCE STUDENT',hero_title VARCHAR(255) DEFAULT 'Building thoughtful digital experiences.',intro TEXT,about_title VARCHAR(255) DEFAULT 'Design-minded. Systems-focused.',about TEXT,about_extra TEXT,skills_label VARCHAR(120) NOT NULL DEFAULT '03 — CAPABILITIES',skills_title VARCHAR(180) NOT NULL DEFAULT 'Learning by',skills_emphasis VARCHAR(120) NOT NULL DEFAULT 'making.',skills_intro TEXT,skills_empty_text VARCHAR(180) NOT NULL DEFAULT 'Skills to be added',gallery_title VARCHAR(180) NOT NULL DEFAULT 'A visual journal',gallery_intro TEXT,email VARCHAR(190),github_url VARCHAR(500),linkedin_url VARCHAR(500),instagram_url VARCHAR(500),resume_url VARCHAR(500),updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,category VARCHAR(120) DEFAULT 'Project',description TEXT,technologies VARCHAR(500),image_url VARCHAR(500),image_alt VARCHAR(255),role VARCHAR(255),status VARCHAR(80) DEFAULT 'In progress',demo_url VARCHAR(500),source_url VARCHAR(500),case_study_url VARCHAR(500),sort_order INT DEFAULT 0,is_published TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS skills(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category VARCHAR(100) NOT NULL,name VARCHAR(120) NOT NULL,level VARCHAR(80),sort_order INT DEFAULT 0,is_published TINYINT(1) DEFAULT 1);
CREATE TABLE IF NOT EXISTS skill_categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,sort_order INT NOT NULL DEFAULT 0,is_published TINYINT(1) NOT NULL DEFAULT 1,logo_1_url VARCHAR(500) DEFAULT NULL,logo_2_url VARCHAR(500) DEFAULT NULL,logo_3_url VARCHAR(500) DEFAULT NULL);
CREATE TABLE IF NOT EXISTS gallery(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,caption VARCHAR(500) DEFAULT NULL,image_url VARCHAR(500) NOT NULL,image_alt VARCHAR(255) NOT NULL,sort_order INT NOT NULL DEFAULT 0,is_published TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contact_portraits(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,image_url VARCHAR(500) NOT NULL,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS timeline(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type VARCHAR(80) DEFAULT 'Education',period VARCHAR(120),title VARCHAR(180) NOT NULL,organization VARCHAR(180),details TEXT,sort_order INT DEFAULT 0,is_published TINYINT(1) DEFAULT 1,logo_url VARCHAR(500) DEFAULT NULL);
CREATE TABLE IF NOT EXISTS site_content(content_key VARCHAR(100) PRIMARY KEY,content_value TEXT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
INSERT INTO profile(name,intro,about,email,github_url,linkedin_url,resume_url) SELECT 'Your Name','Computer Science student focused on web systems, interface design, and useful software.','I am a Computer Science student interested in web systems, UI/UX, and software development.','', '', '', 'assets/documents/resume.pdf' WHERE NOT EXISTS(SELECT 1 FROM profile);
INSERT INTO contact_portraits(image_url,sort_order) SELECT portrait_url,1 FROM profile WHERE id=1 AND portrait_url IS NOT NULL AND portrait_url<>'' AND NOT EXISTS(SELECT 1 FROM contact_portraits);
INSERT IGNORE INTO skill_categories(name,sort_order,is_published) VALUES ('UI/UX Design',1,1),('Frontend Development',2,1),('Backend Development',3,1),('Database',4,1),('Tools and Workflow',5,1);
